package im.tlgxy.cloud.module.ai.model.result;

import lombok.AllArgsConstructor;
import lombok.Data;

import java.util.List;
import im.tlgxy.cloud.module.learning.model.MaterialCitation;
import im.tlgxy.cloud.module.ai.model.automation.Automation;

/** AI Agent 对话结果。 */
@Data
@AllArgsConstructor
public class AiChatResult {

    /** Agent 返回给用户的文本。 */
    private String answer;

    /** 本轮对话中实际执行过的站内工具。 */
    private List<AiToolTrace> tools;

    /** Evidence returned by actual authorized retrieval, never generated by the model. */
    private List<MaterialCitation> citations;
    private List<AiKnowledgeResult> knowledge;
    private List<Automation.View> plans;

    public AiChatResult(String answer, List<AiToolTrace> tools, List<MaterialCitation> citations) {
        this(answer, tools, citations, List.of(), List.of());
    }

    public AiChatResult(String answer, List<AiToolTrace> tools) {
        this(answer, tools, List.of());
    }
}
